  async adminSetUserRoles(id,roles,isAdmin=false){const clean=normalizeRoles(roles).filter(r=>['Beatmaker','Artiste','Producteur','Ingénieur du son','Manager'].includes(r));if(!clean.length)throw new Error('Choisis au moins un rôle.');const u=this.store.users.find(x=>x.id===id);if(u){u.roles=clean;u.is_admin=Boolean(isAdmin);u.role=isAdmin?'Admin':clean[0];}const p=this.store.profiles.find(x=>x.user_id===id);if(p){p.roles=clean;p.is_admin=Boolean(isAdmin);p.role=isAdmin?'Admin':clean[0];}this.persist();}
  async adminCreateUser(data){const previous=localStorage.getItem(this.sessionKey);const created=await this.register(data);if(previous)localStorage.setItem(this.sessionKey,previous);else localStorage.removeItem(this.sessionKey);return created;}

