  async activityFeed(user,limit=24){const profiles=await this.followedProfiles(user),ids=profiles.map(p=>p.user_id),byId=Object.fromEntries(profiles.map(p=>[p.user_id,p]));return clone(this.store.beats.filter(b=>ids.includes(b.producer_id)&&b.visibility==='Publié'&&!b.design?._trashed).sort((a,b)=>new Date(b.updated_at||b.created_at||0)-new Date(a.updated_at||a.created_at||0)).slice(0,limit).map(beat=>({type:'beat',beat,profile:byId[beat.producer_id],created_at:beat.updated_at||beat.created_at||now()})));}
  async getRecommendationPreferences(user){this.store.recommendationPrefs=this.store.recommendationPrefs||{};return clone(this.store.recommendationPrefs[user.id]||{user_id:user.id,preferred_genres:[],hidden_genres:[],preferred_bpm_min:null,preferred_bpm_max:null,preferred_keys:[]});}
  async saveRecommendationPreferences(user,prefs){this.store.recommendationPrefs=this.store.recommendationPrefs||{};this.store.recommendationPrefs[user.id]={...(this.store.recommendationPrefs[user.id]||{}),user_id:user.id,...prefs,updated_at:now()};this.persist();return clone(this.store.recommendationPrefs[user.id]);}
  async recommendedBeats(user,limit=12){const prefs=await this.getRecommendationPreferences(user),followed=(this.store.follows||[]).filter(x=>x.follower_id===user.id).map(x=>x.followed_id),favorites=(this.store.favorites?.[user.id]||[]);return clone(this.store.beats.filter(b=>b.visibility==='Publié'&&!b.design?._trashed&&!(prefs.hidden_genres||[]).includes(b.genre)).map(b=>{let score=Math.log10((Number(b.plays)||0)+10)+(Number(b.likes)||0)/10000;if((prefs.preferred_genres||[]).includes(b.genre))score+=8;if(prefs.preferred_bpm_min&&b.bpm>=prefs.preferred_bpm_min)score+=2;if(prefs.preferred_bpm_max&&b.bpm<=prefs.preferred_bpm_max)score+=2;if((prefs.preferred_keys||[]).includes(b.key))score+=3;if(followed.includes(b.producer_id))score+=5;if(favorites.includes(b.id))score+=4;return{b,score};}).sort((a,b)=>b.score-a.score).slice(0,limit).map(x=>x.b));}
