  async getBadges(){this.store.badges=this.store.badges||[{id:'badge_verified',slug:'verified',name:'Vérifié',description:'Profil vérifié',icon:'✓',style:{accent:'#f6c90e'},active:true},{id:'badge_founder',slug:'founder',name:'Fondateur',description:'Membre fondateur',icon:'♛',style:{accent:'#f6c90e'},active:true},{id:'badge_partner',slug:'partner',name:'Partenaire',description:'Partenaire officiel',icon:'✦',style:{accent:'#7c5cff'},active:true}];return clone(this.store.badges);}
  async getProfileBadges(userId){const badges=await this.getBadges();return clone((this.store.profileBadges||[]).filter(x=>x.user_id===userId).map(x=>badges.find(b=>b.id===x.badge_id)).filter(Boolean));}
