  async adminResolveError(id){const r=await fetch(`${String(CFG.apiBaseUrl||CFG.driveWorkerUrl||'').replace(/\/$/,'')}/admin/error/resolve`,{method:'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${this.session.access_token}`},body:JSON.stringify({errorId:id})});const body=await r.json().catch(()=>({}));if(!r.ok)throw new Error(body.error||'Mise à jour impossible.');return body;}
